#!/usr/bin/env bash
# Homebrew end-to-end test of the formula Hephaestus generates for kirke.
#
# 1. Installs kirke 1.2.8 from the formula currently in magicdrive/homebrew-tap
#    (generated by GoReleaser; read only, pinned to a tap commit).
# 2. Takes the formula Hephaestus generated in <dist>/homebrew/kirke.rb, points
#    its download URLs at the local archives (file://, nothing else changes),
#    runs brew style and brew audit --strict, and upgrades to it.
# 3. Checks the installed binary (--version, a conversion), the bash and
#    zsh completion files (same place and content as with 1.2.8), bash
#    completion registration, brew test, and brew uninstall.
#
# Everything happens in a throw-away tap that is removed on exit. It refuses to
# run when a formula named kirke is already installed, so a workstation's own
# installation is never touched; intended for CI runners and containers.
#
# Usage: scripts/homebrew-e2e.sh <dist-dir> <tag>   (make e2e-homebrew)
set -euo pipefail
export LC_ALL=C

if [[ $# -ne 2 ]]; then
  echo "usage: $0 <dist-dir> <tag>" >&2
  exit 2
fi
dist="$(cd "$1" && pwd)" tag="$2"
version="${tag#v}"
repo="$(cd "$(dirname "$0")/.." && pwd)"
# The tap's kirke.rb for v1.2.8 ("Brew formula update for kirke version
# v1.2.8"), generated by GoReleaser. Read only.
current_formula="https://raw.githubusercontent.com/magicdrive/homebrew-tap/f505572a1b1d6a1e80762b27ddea4089926d0f1e/kirke.rb"
current_version=1.2.8
work="$(mktemp -d)"
tap="kirke-e2e/t$RANDOM$RANDOM"

export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_DEVELOPER=1 HOMEBREW_NO_ASK=1 \
  HOMEBREW_NO_INSTALL_CLEANUP=1 HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1 \
  HOMEBREW_NO_ANALYTICS=1 HOMEBREW_NO_ENV_HINTS=1

if brew list --formula kirke >/dev/null 2>&1; then
  echo "error: a formula named kirke is already installed; run this test on a disposable machine" >&2
  exit 1
fi

# Homebrew 7.0.11 and later load a formula of a tap that is not official only
# once it is trusted (brew trust): brew audit and brew info refuse the
# formula of an untrusted tap. Only the throw-away tap is trusted, while it
# exists (when this Homebrew has brew trust); brew untrust also forgets the
# formula brew install trusts.
trusts=false
brew trust --help >/dev/null 2>&1 && trusts=true

cleanup() {
  set +e
  brew uninstall --force "$tap/kirke" >/dev/null 2>&1
  if [[ "$trusts" == true ]]; then brew untrust --tap "$tap" >/dev/null 2>&1; fi
  brew untap --force "$tap" >/dev/null 2>&1
  rm -rf "$work"
}
trap cleanup EXIT

step() { printf '\n==> %s\n' "$*"; }
fail() { echo "homebrew-e2e: $*" >&2; exit 1; }

prefix="$(brew --prefix)"
bash_file="$prefix/etc/bash_completion.d/kirke"
zsh_file="$prefix/share/zsh/site-functions/_kirke"

check_installed() { # check_installed VERSION
  local out
  out="$("$prefix/bin/kirke" --version)"
  [[ "$out" == "kirke version v$1" ]] || fail "--version printed '$out', want 'kirke version v$1'"
  echo "$out"
  [[ -s "$bash_file" ]] || fail "missing $bash_file"
  [[ -s "$zsh_file" ]] || fail "missing $zsh_file"
  cmp "$bash_file" "$repo/misc/completions/bash/kirke-completion.bash"
  cmp "$zsh_file" "$repo/misc/completions/zsh/_kirke"
  echo "completions: $bash_file, $zsh_file"
}

brew tap-new --no-git "$tap" >/dev/null
if [[ "$trusts" == true ]]; then brew trust --tap "$tap"; fi
formulae="$(brew --repository "$tap")/Formula"

step "kirke $current_version from the tap's current formula (read only)"
curl -fsSL "$current_formula" -o "$formulae/kirke.rb"
grep -q "releases/download/v$current_version/" "$formulae/kirke.rb" || fail "unexpected tap formula"
brew install --formula "$tap/kirke"
check_installed "$current_version"

step "kirke $version: the formula generated by Hephaestus, as it would be published"
generated="$dist/homebrew/kirke.rb"
[[ -f "$generated" ]] || fail "missing $generated (run make e2e-dist)"
cat "$generated"
release_url="https://github.com/magicdrive/kirke/releases/download/$tag/"
[[ "$(grep -c "^      url \"${release_url}kirke_${version}_" "$generated")" == 4 ]] || fail "expected four release URLs for $tag"
cp "$generated" "$formulae/kirke.rb"

step "The formula has none of the problems of the GoReleaser formula"
# brew audit --strict below is the authoritative check; these name the eight
# problems Homebrew 7.0.11 reported for the GoReleaser formula of v1.2.8.
desc="$(sed -n 's/^  desc "\(.*\)"$/\1/p' "$generated")"
[[ -n "$desc" && "${#desc}" -le 80 && "$desc" != *. ]] || fail "desc must be at most 80 characters without a trailing period: '$desc'"
if grep -Eq '^ +version ' "$generated"; then fail "the formula sets a version Homebrew infers from the URLs"; fi
if grep -Eq '^ {3,}def ' "$generated"; then fail "the formula defines a method inside a block"; fi
if grep -Fq '"#{bin}/kirke"' "$generated"; then fail 'the formula uses "#{bin}/kirke" instead of bin/"kirke"'; fi

step "brew style, brew audit --strict, version inferred from the release URLs"
brew style --formula "$tap/kirke"
brew audit --strict --formula "$tap/kirke"
info="$(brew info --formula "$tap/kirke")"
head -1 <<<"$info"
head -1 <<<"$info" | grep -qF "stable $version" || fail "Homebrew does not infer version $version from the formula"

step "The same formula with local archives"
# Only the download URLs change. Homebrew cannot infer the version from a
# file:// path, so the version it inferred above is written out.
sed -e "s|${release_url}|file://${dist}/|" \
  -e "s|^  license \"MIT\"$|  version \"${version}\"\n  license \"MIT\"|" \
  "$generated" > "$formulae/kirke.rb"
if grep -q 'https://github.com/magicdrive/kirke/releases' "$formulae/kirke.rb"; then fail "a release URL was not rewritten"; fi
grep -qx "  version \"${version}\"" "$formulae/kirke.rb" || fail "version line not added"
diff "$generated" "$formulae/kirke.rb" || true

step "brew upgrade $current_version → $version"
brew upgrade --formula "$tap/kirke"
check_installed "$version"

step "Installed kirke converts JSON"
"$prefix/bin/kirke" --pipe --auto-pager off < "$repo/misc/sample.json" | grep -q '^type AutoGenerated struct {'

step "bash completion is registered"
bash --norc --noprofile -c "source '$bash_file' && complete -p kirke" | grep -qx 'complete -F _kirke_completions kirke'
if command -v zsh >/dev/null; then
  zsh -n "$zsh_file"
  echo "zsh: $zsh_file parses"
else
  echo "zsh not installed; syntax check skipped"
fi

step "brew test, brew uninstall"
brew test "$tap/kirke"
# --force: also the 1.2.8 keg kept by HOMEBREW_NO_INSTALL_CLEANUP.
brew uninstall --force "$tap/kirke"
if brew list --formula kirke >/dev/null 2>&1; then fail "kirke is still installed"; fi
[[ ! -e "$prefix/bin/kirke" && ! -e "$bash_file" && ! -e "$zsh_file" ]] || fail "files left behind after uninstall"

echo
echo "Homebrew E2E passed: kirke $current_version (tap) → $version (Hephaestus formula)"
